practice.solution:
package main

import "fmt"

func main() {
	member := true
	order := 30
	if member {
		if order >= 25 {
			fmt.Printf("Order %d: free shipping\n", order)
		} else {
			fmt.Printf("Order %d: pay shipping\n", order)
		}
	} else {
		if order >= 50 {
			fmt.Printf("Order %d: free shipping\n", order)
		} else {
			fmt.Printf("Order %d: pay shipping\n", order)
		}
	}

	member = false
	order = 40
	if order >= 50 || (member && order >= 25) {
		fmt.Printf("Order %d: free shipping\n", order)
	} else {
		fmt.Printf("Order %d: pay shipping\n", order)
	}
}
